sys_ui_action.script:
var handler = new x_hsb11_mss_oper_0.MSS_Operation_Request_Utils();
var nextState = handler.handlePRMprocess(current.state, current.sys_id, 2, current.requesting_country_territory, current.product_team, current.receiving_country_territory, current.receiving_product_team);

if (nextState == -1) {
    gs.addInfoMessage("Missing history records, please cancel and raise new request.");
} else if (nextState == 1) {
    gs.addInfoMessage("The current user already reviewed before, cannot process again.");
} else if (nextState == -2) {
    gs.addInfoMessage("The approver don't have authority to review this request.");
} else if (nextState == 101) {
    gs.addInfoMessage("The approver don't have territory and Team authority to review this request.");
} else if (nextState == 102) {
    gs.addInfoMessage("The approver don't have territory authority to review this request.");
} else if (nextState == 103) {
    gs.addInfoMessage("The approver don't have team authority to review this request.");
} else if (!current.work_notes || current.work_notes.trim() === '') { // Check if Work Notes are empty
    gs.addInfoMessage("Please enter rejection reason in Work Notes before rejecting.");
} else {

    current.state = 4;
    current.update();

    handler.addApprovedList(current.sys_id, gs.getUserID(), current.state, 4);
}
